"""Record scoped Tiling continuity globally and locally using the existing memory."""
from prepare import HERE, ROOT, HALLS, put
import json,sys
sys.path.insert(0,str(ROOT/'tools'))
import project_memory, museum_connections, museum_memory

def main():
    assert not (HERE/'memory-receipt.json').exists(),'Already recorded.'
    report=HERE.relative_to(ROOT).as_posix()
    state=json.loads((ROOT/'doc/book/memory/state.json').read_text(encoding='utf-8'));revision=state['revision'];receipts=[]
    completion='12 October — Tiling continuity: nine current complete tutorials retained, including newer loom and garment passages. Exact Colour PointBody/Palette/GridSurface return; source → reader → frame → glide → copied recipes → optional volume → comparison → fabric. 36 printed file occurrences; 647 native assertions + 12 explicit transfer checks passed. All entry programs and current final texts retained. Only inherited control-hint text changed in code listings. Teacher-authored evidence; no new live installation or headset trial. Five-column/six-column-period limitation remains. '+report+'/index.html'
    for scope,note in [('sequence:tiling',{'summary':completion,'reason':'Author continued one sequence at a time after Colour. Existing complete revisions are the basis; source reuse, explicit copying and saved artifacts have different lifetimes.','open_question':'A wider learner receiver should show complete reflected/glided periods. Review the teaching rhythm with a reader; keep volume and loom/clothing extensions optional.'}),('project',{'summary':state['notes']['project']['summary']+'\n\n'+completion})]:
        result=project_memory.mutate(ROOT,{'action':'note','expected_revision':revision,'scope':scope,'note':note});revision=result['revision'];receipts.append({'action':'note','scope':scope,'revision':revision})
    result=project_memory.mutate(ROOT,{'action':'finding','expected_revision':revision,'finding':{'scope':'sequence:tiling','kind':'source','text':'The nine current Tiling tutorials now have a refreshed paired reading, exact Colour helper continuity and fresh native evidence.','reason':'Complete later revisions already existed. Preserve them, correct stale missing-Ribbon status and make the Colour handoff explicit.','sequence_effect':'Distinct jobs remain: return, source edit, reader change, physical frame, glide, composition, optional volume, perceptual pause, shader. Five-column display does not show the full reflected period.','project_effect':'Colour classes return unchanged; explicit copied values and saved loom records are not confused with automatic inter-hall persistence. Current reflections retain their own questions.','method':'Current-source comparison; 36 exact printed file occurrences; 647 native assertions including GPU sampling; 12 cross-hall transfer assertions; current final/configuration hashes preserved.','created_by':'Codex Tiling continuity 2026-10-12','related_scopes':['project','sequence:color','sequence:change'],'source_paths':[f'commons/maps/{h}/tutorial.md' for h in HALLS]+[report+'/'+n for n in ['sequence-verification.json','changes.json','plan-receipt.json','lineage.json']]}})
    revision=result['revision'];receipts.append({'action':'finding','revision':revision})
    connections=museum_connections.read(ROOT);cr=connections['revision'];old=connections['summaries']['sequence:tiling']
    paths=list(dict.fromkeys(list(old['sources'])+[f'commons/maps/{h}/tutorial.md' for h in HALLS]+[report+'/sequence-verification.json',report+'/lineage.json']))
    result=museum_connections.mutate(ROOT,{'action':'summary','expected_revision':cr,'id':'sequence:tiling','record':{'summary':'Colour’s familiar point, palette and addressed cubes return. One source reaches many places through wrapped, reflected and glided readings; physical frames give addresses a place, and copied recipes can diverge. Volume is a branch, perception a pause, and UV sampling puts a known operation on a garment. The newer optional loom and cutting encounters remain.','carry':'Exact PointBody, Palette and GridSurface source reuse from Colour; explicitly copied records in Temple. Most study states initialize afresh. SAVE CLOTH → LOAD LOOM is a separate saved record from the fabric studio recipe; the latter does not save a changed shader. 647 native assertions + 12 transfer checks, 12 October.','question':'What stays fixed when the pattern changes, and what survives the next room? Keep the incomplete six-column period visible as a limitation of the small five-column receiver.','source_paths':paths}});cr=result['revision'];receipts.append(result)
    edges=[
        ('tiling-colour-helpers','map:Color_Grid_Pallet','map:Pattern_Disco','rule','reuses','Disco prints the exact current Colour Palette and GridSurface helpers; PointBody also matches Colour Nails. A new calculated checker separates phase from palette while the receiver stays fixed. This is class reuse, not transfer of a running palette or saved edit.',['commons/maps/Color_Grid_Pallet/tutorial.md','commons/maps/Color_Nails/tutorial.md','commons/maps/Pattern_Disco/tutorial.md',report+'/sequence-verification.json']),
        ('tiling-saved-cloth','map:Symmetry_Seventeen','map:Ribbon_Patterns_03','trace','reuses','Current tutorials document the optional installed SAVE CLOTH → LOAD LOOM handoff: crossings and yarn colours become input to the cutting table. This record is separate from the shader studio source and recipe. The later passages are retained; this pass does not newly certify loom or garment runtime.',['commons/maps/Symmetry_Seventeen/tutorial.md','commons/maps/Ribbon_Patterns_03/tutorial.md']),
    ]
    for id,source,target,thread,relation,reason,paths in edges:
        result=museum_connections.mutate(ROOT,{'action':'connection','expected_revision':cr,'id':id,'record':{'from':source,'to':target,'thread':thread,'relation':relation,'status':'documented','reason':reason,'source_paths':paths}});cr=result['revision'];receipts.append(result)
    p=ROOT/'doc/book/course/storyboards/CONTEXT.md';t=p.read_text(encoding='utf-8');heading='# Move between whole and part\n\n';assert t.startswith(heading)
    put(p,heading+'**'+completion+'** Paired review and editable summaries published. One sequence only. Do not rerun one-shot prepare/plan/memory scripts; the next requested sequence is Change.\n\n'+t[len(heading):])
    model=museum_memory.model(ROOT)
    for scope in ['project','sequence:tiling']:
        assert 'Tiling continuity' in json.dumps(museum_memory.packet(model,scope),ensure_ascii=False),scope
    put(HERE/'memory-receipt.json',json.dumps({'project_memory_revision':revision,'connections_revision':cr,'packet_visibility':['project','sequence:tiling'],'receipts':receipts},ensure_ascii=False,indent=2)+'\n')
    print('Tiling memory and Colour/source-record connections updated; context packets verified.')

if __name__=='__main__':main()
